/** Todas las partes que `CATALOGO_DE_TEXTOS` junta con un spread. */
const PARTES: readonly object[] = [
  TEXTOS_DE_CAJA,
  TEXTOS_DE_CARTA_PUBLICA,
  TEXTOS_DE_CATALOGO,
  TEXTOS_DE_CIERRE,
  TEXTOS_DE_CLIENTES,
  TEXTOS_DE_COMANDAS,
  TEXTOS_DE_COMPRAS,
  TEXTOS_DE_FISCAL_CONFIGURACION,
  TEXTOS_DE_FISCAL_EMITIR,
  TEXTOS_DE_FISCAL_IMPRIMIR,
  TEXTOS_DE_FISCAL_PANTALLAS,
  TEXTOS_DE_FISCAL,
  TEXTOS_DE_LOTES,
  TEXTOS_DEL_NUCLEO,
  TEXTOS_DE_PRODUCCION,
  TEXTOS_DE_SALON,
  TEXTOS_DE_SESION_Y_EMPRESA,
  TEXTOS_DE_STOCK,
  TEXTOS_DE_USUARIOS,
  TEXTOS_DE_VENTAS,
];

/** Las claves que figuran en más de una parte (un spread posterior pisaría a otro en silencio). */
function clavesRepetidas(partes: readonly object[]): string[] {
  const vistas = new Set<string>();
  const repetidas = new Set<string>();
  for (const parte of partes) {
    for (const clave of Object.keys(parte)) {
      if (vistas.has(clave)) repetidas.add(clave);
      vistas.add(clave);
    }
  }
  return [...repetidas];
}

describe("el catálogo de textos partido en archivos", () => {
  it("es idéntico, con el orden de claves, al de antes de partirlo", () => {
    expect(JSON.stringify(CATALOGO_DE_TEXTOS)).toBe(CATALOGO_CONGELADO);
  });

  it("ninguna clave vive en dos archivos y las partes suman todo el catálogo", () => {
    expect(PARTES).toHaveLength(20);
    expect(clavesRepetidas(PARTES)).toEqual([]);
    const suma = PARTES.reduce<number>((n, parte) => n + Object.keys(parte).length, 0);
    expect(suma).toBe(Object.keys(CATALOGO_DE_TEXTOS).length);
  });

  it("detecta una clave repetida en dos partes", () => {
    const repetida = [{ "a.b": 1 }, { "a.b": 2, "a.c": 3 }];
    expect(clavesRepetidas(repetida)).toEqual(["a.b"]);
  });

  it("ClaveDeTexto sigue cerrada: no se ensancha a cualquier texto", () => {
    expectTypeOf<string>().not.toEqualTypeOf<ClaveDeTexto>();
    expectTypeOf<"clave.que.no.existe">().not.toExtend<ClaveDeTexto>();
  });
});
